mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM dining_tables
    WHERE store_id = #{storeId}
      AND code = #{code}
)

mapper.delete:
DELETE FROM dining_tables
WHERE store_id = #{storeId}
  AND id = #{tableId}

DELETE table_qr_codes
FROM table_qr_codes
INNER JOIN dining_tables ON dining_tables.id = table_qr_codes.table_id
WHERE dining_tables.store_id = #{storeId}
  AND dining_tables.id = #{tableId}

mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM orders
    WHERE sales_session_id = #{sessionId}
)

SELECT id
FROM client_accounts
WHERE store_id = #{storeId}
  AND phone = #{phone}

